  document.getElementById("theme-tray")?.hidePopover?.();
  const ed = window.tinymce?.activeEditor;
  if (!ed) return "no editor";
  ed.execCommand("pantokenOpenIcons");
  const root = document.getElementById("pantoken-icon-picker");
  return {
    mounted: !!root,
    tiles: root?.querySelectorAll(".pantoken-ip__tile").length ?? 0,
    tabs: [...(root?.querySelectorAll(".pantoken-ip__tab") ?? [])].map((t) => t.textContent),
    status: root?.querySelector(".pantoken-ip__status")?.textContent,
    sheets: document.head.querySelectorAll("[data-pantoken-icon-picker]").length,
  };
});

